-- A join that missed a brewery would drop its beers silently.
DO $$
BEGIN
    IF (SELECT count(*) FROM catalog.brewery WHERE source = 'WIKIDATA') <> 4894
        OR (SELECT count(*) FROM catalog.beer WHERE source = 'WIKIDATA') <> 13553 THEN
        RAISE EXCEPTION 'Wikidata import row counts differ from the generated migration';
    END IF;
END
$$;
